        total = total.saturating_add(u32::from(self.inspect_script_type_name(line)));
        total = total.saturating_add(u32::from(self.inspect_script_comment_gap(line)));
        total = total.saturating_add(u32::from(self.inspect_unclosed_script_block(line)));
        total = total.saturating_add(u32::from(self.inspect_script_toml_table(line)));
        total = total.saturating_add(u32::from(self.inspect_script_array_open(line)));
        total = total.saturating_add(u32::from(self.inspect_script_array_close(line)));
        total = total.saturating_add(u32::from(self.inspect_script_quoted_value(line)));
        total = total.saturating_add(u32::from(self.inspect_script_triple_quote(line)));
        total = total.saturating_add(u32::from(self.inspect_script_line_continuation(line)));
        total = total.saturating_add(u32::from(self.inspect_script_requires_quote(line)));
        total = total.saturating_add(u32::from(self.inspect_script_dep_version(line)));
        total = total.saturating_add(u32::from(self.inspect_script_dep_lower(line)));
        total = total.saturating_add(u32::from(self.inspect_script_dep_upper(line)));
        total = total.saturating_add(u32::from(self.inspect_script_inline_comment(line)));
        total = total.saturating_add(u32::from(self.inspect_script_dotted_tool(line)));
        total = total.saturating_add(u32::from(self.inspect_script_index_https(line)));
        total = total.saturating_add(u32::from(self.inspect_script_index_simple(line)));
        total = total.saturating_add(u32::from(self.inspect_script_pep723_marker(line)));
        total = total.saturating_add(u32::from(self.inspect_script_metadata_space(line)));
        total = total.saturating_add(u32::from(self.inspect_script_bool_true(line)));
        total = total.saturating_add(u32::from(self.inspect_script_bool_false(line)));
        total = total.saturating_add(u32::from(self.inspect_script_project_table(line)));
        total = total.saturating_add(u32::from(self.inspect_script_build_system(line)));
        total
    }

    fn observe_shebang_features(&mut self, line: &str) -> u32 {
        let mut total = 0u32;
        total = total.saturating_add(u32::from(self.inspect_hashbang_prefix(line)));
        total = total.saturating_add(u32::from(self.inspect_env_interpreter(line)));
