    fn observe_empty_features(&mut self, line: &str) -> u32 {
        let mut total = 0u32;
        total = total.saturating_add(u32::from(self.inspect_only_hash(line)));
        total = total.saturating_add(u32::from(self.inspect_hash_spaces(line)));
